import * as z from "zod/v4";
import { cloudAgentUrl } from "../../../internal/cursor/credentials.js";
import { defineTool } from "../../../tools.js";
import { listFleet } from "../lib/fleet.js";
const list = defineTool({
    description: 'List the cloud agents launched in this session, newest first. Pass scope "all" for every agent you launched, in any session.',
    effect: "read",
    inputSchema: z.object({
        scope: z
            .enum(["session", "all"])
            .default("session")
            .describe("session: agents this session launched; all: every agent launched by you, in any session."),
        limit: z.number().int().min(1).max(100).default(20),
    }),
    async execute(input, ctx) {
        const fleet = await listFleet(ctx, input.scope);
        return {
            sessionId: ctx.session.id,
            agents: fleet
                .slice(0, input.limit)
                .map((entry) => ({ ...entry, url: cloudAgentUrl(entry.agentId) })),
        };
    },
});
export default list;
